namespace UniversityCourseCatalog.Models;

public class Department
{
    public string Id { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public string Id { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string DepartmentId { get; set; } = string.Empty;
    public string DepartmentName { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z]{2}\d{6}$", ErrorMessage = "Student ID must be 2 uppercase letters followed by 6 digits (e.g., CS123456).")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    public string CourseId { get; set; } = string.Empty;
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = "cs", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = "math", Name = "Mathematics", Description = "Pure and applied mathematics including statistics and analysis." },
            new() { Id = "phys", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = "eng", Name = "English", Description = "Literature, writing, and language studies." },
            new() { Id = "hist", Name = "History", Description = "Study of past events and their impact on the modern world." },
        };

        _courses = new List<Course>
        {
            new() { Id = "cs101", Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", DepartmentId = "cs", DepartmentName = "Computer Science", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a PhD from MIT.", IsFeatured = true },
            new() { Id = "cs201", Code = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques including sorting, searching, and dynamic programming.", DepartmentId = "cs", DepartmentName = "Computer Science", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park specializes in algorithm optimization and has published over 40 papers in top conferences.", IsFeatured = true },
            new() { Id = "cs310", Code = "CS 310", Title = "Database Systems", Description = "Relational database design, SQL, transaction processing, and introduction to NoSQL databases.", DepartmentId = "cs", DepartmentName = "Computer Science", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Maria Garcia", InstructorBio = "Dr. Garcia worked at Oracle for a decade before joining academia. Her research focuses on distributed databases." },
            new() { Id = "math101", Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", DepartmentId = "math", DepartmentName = "Mathematics", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Liu", InstructorBio = "Dr. Liu is a renowned mathematician specializing in analysis. He has taught calculus for over 20 years.", IsFeatured = true },
            new() { Id = "math201", Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications.", DepartmentId = "math", DepartmentName = "Mathematics", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Emily Watson", InstructorBio = "Dr. Watson's research bridges pure mathematics and machine learning applications." },
            new() { Id = "math301", Code = "MATH 301", Title = "Probability & Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", DepartmentId = "math", DepartmentName = "Mathematics", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Emily Watson", InstructorBio = "Dr. Watson's research bridges pure mathematics and machine learning applications." },
            new() { Id = "phys101", Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions.", DepartmentId = "phys", DepartmentName = "Physics", Credits = 4, Schedule = "Tue/Thu 9:00–10:15 AM + Fri Lab", InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster is an experimental physicist who previously worked at CERN." },
            new() { Id = "phys201", Code = "PHYS 201", Title = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves.", DepartmentId = "phys", DepartmentName = "Physics", Credits = 4, Schedule = "Mon/Wed 3:30–4:45 PM + Thu Lab", InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster is an experimental physicist who previously worked at CERN.", IsFeatured = true },
            new() { Id = "eng101", Code = "ENG 101", Title = "College Writing", Description = "Develop clear, effective writing skills through essays, research papers, and peer review.", DepartmentId = "eng", DepartmentName = "English", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", InstructorName = "Prof. Diana Reeves", InstructorBio = "Prof. Reeves is a published author and has taught composition and rhetoric for 12 years." },
            new() { Id = "eng205", Code = "ENG 205", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present, including poetry, fiction, and essays.", DepartmentId = "eng", DepartmentName = "English", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Prof. Diana Reeves", InstructorBio = "Prof. Reeves is a published author and has taught composition and rhetoric for 12 years." },
            new() { Id = "hist101", Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, events, and cultural developments from prehistory to 1500 CE.", DepartmentId = "hist", DepartmentName = "History", Credits = 3, Schedule = "Tue/Thu 2:30–3:45 PM", InstructorName = "Dr. Michael Torres", InstructorBio = "Dr. Torres is an expert in ancient civilizations with archaeological fieldwork experience across three continents." },
            new() { Id = "hist202", Code = "HIST 202", Title = "Modern World History", Description = "Major political, economic, and social developments from the Enlightenment to the present day.", DepartmentId = "hist", DepartmentName = "History", Credits = 3, Schedule = "Mon/Wed 10:00–11:15 AM", InstructorName = "Dr. Michael Torres", InstructorBio = "Dr. Torres is an expert in ancient civilizations with archaeological fieldwork experience across three continents." },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(string id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? departmentId = null, string? searchTerm = null)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentId))
        {
            query = query.Where(c => c.DepartmentId == departmentId);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(string id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();
}

